mapper.select:
SELECT id, review_id, reporter_id, reason, status, handler_id, handled_at, create_time, update_time
FROM show_review_report

    AND status = #{status}

ORDER BY id DESC
LIMIT #{size} OFFSET #{offset}

mapper.update:
UPDATE show_review_report
SET status = #{status}, handler_id = #{handlerId}, handled_at = #{handledAt}, update_time = NOW()
WHERE id = #{id}

mapper.select:
SELECT COUNT(1) FROM show_review_report
WHERE reporter_id = #{reporterId} AND review_id = #{reviewId}
LIMIT 1
